@startuml

class Product {
  + name : string
  + description : string
  + netPrice : double
}

class Manufacturer {
  + name : string
}

class Country {
  + name : string
  + vatRate : double
  + currency : string
  + conversionRateToEuro : double
}

class Representative {
  + firstName : string
  + lastName : string
  + socialSecurityNumber : string
  + telephoneNumber : string
  + emailAddress : string
}

class Customer {
  + name : string
  + address : string
  + telephoneNumber : string
  + emailAddress : string
}

class Order {
  + orderId : string
  + quantity : int
  + orderDate : date
  + desiredDeliveryDate : date
}

Product "*" -- "1" Manufacturer : manufacturedBy
Product "*" -- "1..*" Country : availableIn
Representative "1" -- "1" Country : responsibleFor
Customer "*" -- "1..*" Country : resellsIn
Representative "1" -- "0..*" Order : places
Order "*" -- "1" Product : refersTo

@enduml

